import React from "react";
import gameingcontroller from "../assets/images/gameing-controller.png";
import bag from "../assets/images/bag.png";
import speaker from "../assets/images/speaker.png";
import jacket from "../assets/images/images/jacket.png";
import { RiDeleteBin6Line } from "react-icons/ri";
import { Link } from "react-router-dom";

const products = [
  {
    image: bag,
    icon: <RiDeleteBin6Line />,
    discount: "-35%",
    name: "HAVIT HV-G92 Gamepad",
    price1: "$120",
    price2: "$160",
  },
  {
    image: speaker,
    icon: <RiDeleteBin6Line />,
    name: "AK-900 Wired Keyboard",
    price1: "$960",
    price2: "$1160",
  },
  {
    image: gameingcontroller,
    icon: <RiDeleteBin6Line />,
    name: "IPS LCD Gaming Monitor",
    price1: "$370",
    price2: "$400",
  },
  {
    image: jacket,
    icon: <RiDeleteBin6Line />,
    name: "S-Series Comfort Chair",
    price1: "$375",
    price2: "$400",
  },
];

const WishListCard = () => {
  const renderProductCards = () => {
    return products.map((product, index) => (
      <div key={index} className="col-xl-3 col-lg-4 col-md-6 col-sm-12">
        <Link to="/Wishlist">
          <div className="image d-flex justify-content-center">
            {product.discount ? (
              <>
                <img src={product.image} alt={product.name} />
                <li className="icons text-black">{product.icon}</li>
                <div className="py-1 px-3 helo">{product.discount}</div>
                <button className="btn btn-dark position-absolute bottom-0 w-100">Add to Cart</button>

              </>
            ) : (
              <>
                <img src={product.image} alt={product.name} />
                <li className="icons text-black">{product.icon}</li>
                <button className="btn btn-dark position-absolute bottom-0 w-100">Add to Cart</button>
              </>
            )}
          </div>
        </Link>
        <div className="heading mt-3">
          <p>{product.name}</p>
        </div>
        <div className="d-flex gap-2">
          <p className="price-1">{product.price1}</p>
          <p className="price-2">{product.price2}</p>
        </div>
      </div>
    ));
  };

  return (
    <div className="container mt-5 mb-5">
      <div className="row">
        <div className="d-flex align-items-center col-md-12 gap-3 py-3 d-flex justify-content-between">
          <h2 className="text-black">Wishlist ({products.length})</h2>
          <button className="bg-white border border-1 border-dark px-5 py-2 text-black">Move All To Bag</button>
        </div>
      </div>
      <div className="row my-3 d-flex align-items-center">
        {renderProductCards()}
      </div>
    </div>
  );
};

export default WishListCard;
