import React, { useState } from "react";
import { Form, Button, Col, Row } from "react-bootstrap";
import { Link } from "react-router-dom";
import moniter from "../assets/images/moniter.png";
import gameingcontroller from "../assets/images/gameing-controller.png";
import BankOption from "../assets/images/bank option.png";
import { InputGroup } from "react-bootstrap";

const CheckOutPage = () => {
  const [formData, setFormData] = useState({
    name: "",
    companyName: "",
    streetAddress: "",
    apartmentFloor: "",
    city: "",
    phoneNumber: "",
    emailAddress: "",
    agreedToTerms: false,
  });

  const [errors, setErrors] = useState({});

  const validate = () => {
    const newErrors = {};
    if (!formData.name) newErrors.name = "Name is required";
    if (!formData.companyName)
      newErrors.companyName = "Company name is required";
    if (!formData.streetAddress)
      newErrors.streetAddress = "Street address is required";
    if (!formData.apartmentFloor)
      newErrors.apartmentFloor = "Apartment/Floor is required";
    if (!formData.city) newErrors.city = "City is required";
    if (!formData.phoneNumber) {
      newErrors.phoneNumber = "Phone number is required";
    } else if (!/^\d{10}$/.test(formData.phoneNumber)) {
      newErrors.phoneNumber = "Phone number must be 10 digits";
    }
    if (!formData.emailAddress) {
      newErrors.emailAddress = "Email address is required";
    } else if (!/\S+@\S+\.\S+/.test(formData.emailAddress)) {
      newErrors.emailAddress = "Email address is invalid";
    }
    if (!formData.agreedToTerms)
      newErrors.agreedToTerms = "You must agree to the terms";

    return newErrors;
  };

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({
      ...formData,
      [name]: type === "checkbox" ? checked : value,
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = validate();
    if (Object.keys(newErrors).length === 0) {
      alert("Form submitted successfully!");
      // Submit form logic here
    } else {
      setErrors(newErrors);
    }
  };

  return (
    <>
      <div className="container mt-4 mb-4">
        <ul className="d-flex list-unstyled gap-2 align-items-center mb-0">
          <li>
            <Link to="/" className="text-decoration-none text-muted">
              Account
            </Link>
          </li>
          <li className="text-muted">/</li>
          <li>
            <Link to="/" className="text-decoration-none text-muted">
              My Account
            </Link>
          </li>
          <li className="text-muted">/</li>
          <li>
            <Link to="/" className="text-decoration-none text-muted">
              Product
            </Link>
          </li>
          <li className="text-muted">/</li>
          <li>
            <Link to="/" className="text-decoration-none text-muted">
              View Cart
            </Link>
          </li>
          <li className="text-muted">/</li>
          <li className="text-dark fw-bold">CheckOut</li>
        </ul>
      </div>

      <div className="container mt-5 mb-5">
        <div className="row">
          <div className="col-md-6">
            <div>
              <h1>Billing Details</h1>
            </div>
            <div>
              <Form onSubmit={handleSubmit}>
                <Form.Group
                  as={Row}
                  controlId="formName"
                  className="d-flex flex-column mb-4"
                >
                  <Form.Label column sm={2} className="text-muted">
                    Name
                  </Form.Label>
                  <Col sm={10}>
                    <Form.Control
                      type="text"
                      name="name"
                      value={formData.name}
                      onChange={handleChange}
                      isInvalid={!!errors.name}
                      className="border-0 bg-light py-3"
                    />
                    <Form.Control.Feedback type="invalid">
                      {errors.name}
                    </Form.Control.Feedback>
                  </Col>
                </Form.Group>

                <Form.Group
                  as={Row}
                  controlId="formCompanyName"
                  className="d-flex flex-column mb-4"
                >
                  <Form.Label Row sm={2} className="text-muted">
                    Company Name
                  </Form.Label>
                  <Col sm={10}>
                    <Form.Control
                      type="text"
                      name="companyName"
                      value={formData.companyName}
                      onChange={handleChange}
                      isInvalid={!!errors.companyName}
                      className="border-0 bg-light py-3"
                    />
                    <Form.Control.Feedback type="invalid">
                      {errors.companyName}
                    </Form.Control.Feedback>
                  </Col>
                </Form.Group>

                <Form.Group
                  as={Row}
                  controlId="formStreetAddress"
                  className="d-flex flex-column mb-4"
                >
                  <Form.Label Row sm={2} className="text-muted">
                    Street Address
                  </Form.Label>
                  <Col sm={10}>
                    <Form.Control
                      type="text"
                      name="streetAddress"
                      value={formData.streetAddress}
                      onChange={handleChange}
                      isInvalid={!!errors.streetAddress}
                      className="border-0 bg-light py-3"
                    />
                    <Form.Control.Feedback type="invalid">
                      {errors.streetAddress}
                    </Form.Control.Feedback>
                  </Col>
                </Form.Group>

                <Form.Group
                  as={Row}
                  controlId="formApartmentFloor"
                  className="d-flex flex-column mb-4"
                >
                  <Form.Label column sm={2} className="text-muted">
                    Apartment/Floor
                  </Form.Label>
                  <Col sm={10}>
                    <Form.Control
                      type="text"
                      name="apartmentFloor"
                      value={formData.apartmentFloor}
                      onChange={handleChange}
                      isInvalid={!!errors.apartmentFloor}
                      className="border-0 bg-light py-3"
                    />
                    <Form.Control.Feedback type="invalid">
                      {errors.apartmentFloor}
                    </Form.Control.Feedback>
                  </Col>
                </Form.Group>

                <Form.Group
                  as={Row}
                  controlId="formCity"
                  className="d-flex flex-column mb-4"
                >
                  <Form.Label column sm={2} className="text-muted">
                    City
                  </Form.Label>
                  <Col sm={10}>
                    <Form.Control
                      type="text"
                      name="city"
                      value={formData.city}
                      onChange={handleChange}
                      isInvalid={!!errors.city}
                      className="border-0 bg-light py-3"
                    />
                    <Form.Control.Feedback type="invalid">
                      {errors.city}
                    </Form.Control.Feedback>
                  </Col>
                </Form.Group>

                <Form.Group
                  as={Row}
                  controlId="formPhoneNumber"
                  className="d-flex flex-column mb-4"
                >
                  <Form.Label Row sm={2} className="text-muted">
                    Phone Number
                  </Form.Label>
                  <Col sm={10}>
                    <Form.Control
                      type="text"
                      name="phoneNumber"
                      value={formData.phoneNumber}
                      onChange={handleChange}
                      isInvalid={!!errors.phoneNumber}
                      className="border-0 bg-light py-3"
                    />
                    <Form.Control.Feedback type="invalid">
                      {errors.phoneNumber}
                    </Form.Control.Feedback>
                  </Col>
                </Form.Group>

                <Form.Group
                  as={Row}
                  controlId="formEmailAddress"
                  className="d-flex flex-column mb-4"
                >
                  <Form.Label Row sm={2} className="text-muted">
                    Email Address
                  </Form.Label>
                  <Col sm={10}>
                    <Form.Control
                      type="email"
                      name="emailAddress"
                      value={formData.emailAddress}
                      onChange={handleChange}
                      isInvalid={!!errors.emailAddress}
                      className="border-0 bg-light py-3"
                    />
                    <Form.Control.Feedback type="invalid">
                      {errors.emailAddress}
                    </Form.Control.Feedback>
                  </Col>
                </Form.Group>

                <Form.Group
                  as={Row}
                  controlId="formAgreedToTerms"
                  className="d-flex flex-column mb-4 justify-content-start"
                >
                  <Col sm={{ span: 10, offset: 2 }}>
                    <Form.Check
                      type="checkbox"
                      label="Save this information for faster check-out next time"
                      name="agreedToTerms"
                      checked={formData.agreedToTerms}
                      onChange={handleChange}
                      isInvalid={!!errors.agreedToTerms}
                      feedback={errors.agreedToTerms}
                      className="fs-5 text-black"
                    />
                  </Col>
                </Form.Group>
              </Form>
            </div>
          </div>
          <div className="col-md-6 mt-5 py-5 px-5">
            <div className="d-flex justify-content-between align-items-center mb-4">
              <div className="d-flex align-items-center gap-4">
                <img
                  src={gameingcontroller}
                  alt=""
                  style={{ width: "54px", height: "54px" }}
                />
                <p className="fs-5 text-black">LCD Moniter</p>
              </div>
              <div>
                <p className="fs-5">$650</p>
              </div>
            </div>
            <div className="d-flex justify-content-between align-items-center mb-4 ">
              <div className="d-flex align-items-center gap-4">
                <img
                  src={moniter}
                  alt=""
                  style={{ width: "54px", height: "54px" }}
                />
                <p className="fs-5 text-black">H1 Gamepad</p>
              </div>
              <div>
                <p className="fs-5">$1100</p>
              </div>
            </div>

            <div className="d-flex justify-content-between align-items-center ">
              <p className="fs-5">SubTotal:</p>
              <p className="fs-5">$1750</p>
            </div>
            <hr />
            <div className="d-flex justify-content-between align-items-center ">
              <p className="fs-5">Shipping:</p>
              <p className="fs-5">Free</p>
            </div>
            <hr />
            <div className="d-flex justify-content-between align-items-center mb-3 ">
              <p className="fs-5">Total:</p>
              <p className="fs-5">$1750</p>
            </div>

            <div className="d-flex justify-content-between align-items-center mb-3 ">
              <p className="fs-5">Bank</p>
              <img
                src={BankOption}
                alt=""
                style={{ width: "192px", height: "28px" }}
              />
            </div>
            <div className="d-flex justify-content-between align-items-center mb-3 ">
              <p className="fs-5">Cash On Delivery</p>
            </div>

            {/* Coupon Code Section */}

            <div className="d-flex flex-column flex-sm-row gap-3 mb-4">
              <Form className="w-100">
                <Form.Group controlId="formCouponCode">
                  <InputGroup>
                    <Form.Control
                      type="text"
                      placeholder="Enter coupon code"
                      aria-label="Coupon code"
                    />
                  </InputGroup>
                </Form.Group>
              </Form>
              <Button
                variant="danger"
                className="d-flex justify-content-center py-2 px-5 w-100 w-sm-auto"
              >
                Apply Coupon
              </Button>
            </div>
            <div>
            <Button
                variant="danger"
                className="d-flex justify-content-center py-2 px-5"
              >
                Place Order
              </Button>
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

export default CheckOutPage;
