import React from "react";
import { Link } from "react-router-dom";
import { Form, InputGroup, Button } from "react-bootstrap";
import { useSelector, useDispatch } from "react-redux";
import { remove } from '../store/CartSlice';

const Cart = () => {
  const dispatch = useDispatch();

  const products = useSelector((state) => state.cart); // Assuming 'cart' is an array of products

  const handleRemove = (ProductId) => {
    dispatch(remove(ProductId));
  };

  return (
    <>
      <div className="container mt-4 mb-4">
        <ul className="d-flex list-unstyled gap-2 align-items-center mb-0">
          <li>
            <Link to="/" className="text-decoration-none text-muted">
              Home
            </Link>
          </li>
          <li className="text-muted">/</li>
          <li className="text-dark fw-bold">Cart</li>
        </ul>
      </div>

      <div className="container">
        <div className="row mt-4 mb-4">
          {/* Header Row */}
          <div className="col-12">
            <div className="d-flex justify-content-between align-items-center shadow-sm p-3 mb-3 bg-body rounded">
              <p className="mb-0">Product</p>
              <p className="mb-0">Price</p>
              <p className="mb-0">Quantity</p>
              <p className="mb-0">Subtotal</p>
            </div>
          </div>

          {/* Product Rows */}
          {products.map((item, index) => (
            <div className="col-12" key={index}>
              <div className="d-flex justify-content-between align-items-center shadow-sm p-3 mb-3 bg-body rounded">
                <div className="d-flex align-items-center gap-3">
                  <img
                    src={item.image}
                    alt={item.name}
                    className="img-fluid"
                    style={{ maxWidth: "80px" }}
                  />
                  <p className="mb-0">{item.name}</p>
                </div>
                <p className="mb-0">{item.price1}</p>
                <div className="col-4 col-md-3 col-lg-2 p-0">
                  <Form.Group controlId={`quantity-${item.id}`}>
                    <InputGroup hasValidation>
                      <Form.Control
                        type="number"
                        placeholder={item.quantity}
                        aria-describedby="inputGroupPrepend"
                        required
                        className="bg-light border-0 text-center"
                      />
                    </InputGroup>
                  </Form.Group>
                </div>
                <p className="mb-0">{item.price1}</p> {/* Subtotal */}
                <button
                  className="btn"
                  onClick={() => handleRemove(item.id)}
                >
                  Remove
                </button>
              </div>
            </div>
          ))}

          {/* Buttons */}
          <div className="col-12 d-flex justify-content-between mt-3">
            <Button variant="light" className="py-2 px-4">
              Return To Shop
            </Button>
            <Button variant="light" className="py-2 px-4">
              Update Cart
            </Button>
          </div>
        </div>
      </div>

      <div className="container mb-5">
        <div className="row">
          {/* Coupon Code Section */}
          <div className="col-12 col-lg-6 mb-4 mb-lg-0">
            <div className="d-flex flex-column flex-sm-row gap-3">
              <Form className="w-100">
                <Form.Group controlId="formCouponCode">
                  <InputGroup>
                    <Form.Control
                      type="text"
                      placeholder="Enter coupon code"
                      aria-label="Coupon code"
                    />
                  </InputGroup>
                </Form.Group>
              </Form>
              <Button variant="danger" className="py-2 px-5 w-100 w-sm-auto">
                Apply Coupon
              </Button>
            </div>
          </div>

          {/* Cart Total Section */}
          <div className="col-xl-12">
            <div className="py-3 px-4 border rounded">
              <div className="mb-4">
                <p className="fs-4 fw-bold text-black">Cart Total</p>
              </div>
              <div className="d-flex justify-content-between">
                <p>SubTotal:</p>
                <p>$1750</p> {/* Placeholder - replace with dynamic value */}
              </div>
              <hr />
              <div className="d-flex justify-content-between">
                <p>Shipping:</p>
                <p>Free</p>
              </div>
              <hr />
              <div className="d-flex justify-content-between">
                <p>Total:</p>
                <p>$1750</p> {/* Placeholder - replace with dynamic value */}
              </div>
              <div className="d-flex justify-content-center mt-4">
                <Link to="/CheckOutPage">
                  <Button variant="danger" className="py-2 px-5">
                    Proceed To Checkout
                  </Button>
                </Link>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

export default Cart;
