import React from "react";
import laptop from "../assets/images/images/laptop.png";
import gameingcontroller from "../assets/images/gameing-controller.png";
import keyboard from "../assets/images/keyboard.png";
import moniter from "../assets/images/moniter.png";
import fivestar from "../assets/images/Five star.png";
import { IoEyeOutline } from "react-icons/io5";
import { Link } from "react-router-dom";

const products = [
  {
    image: laptop,
    icon: <IoEyeOutline />,
    discount: "-35%",
    name: "HAVIT HV-G92 Gamepad",
    price1: "$120",
    price2: "$160",
    star:fivestar,
    reviews:"65",
  },
  {
    image: moniter,
    icon: <IoEyeOutline />,
    name: "AK-900 Wired Keyboard",
    price1: "$960",
    price2: "$1160",
    star:fivestar,
    reviews:"65",
  },
  {
    image: gameingcontroller,
    icon: <IoEyeOutline />,
    name: "IPS LCD Gaming Monitor",
    price1: "$370",
    price2: "$400",
    star:fivestar,
    reviews:"65",
  },
  {
    image: keyboard,
    icon: <IoEyeOutline />,
    name: "S-Series Comfort Chair",
    price1: "$375",
    price2: "$400",
    star:fivestar,
    reviews:"65",
  },
];

const JustForYou = () => {
  const renderProductCards = () => {
    return products.map((product, index) => (
      <div key={index} className="col-xl-3 col-lg-4 col-md-6 col-sm-12">
        <Link to="/Wishlist">
          <div className="image d-flex justify-content-center">
            {product.discount ? (
              <>
                <img src={product.image} alt={product.name} />
                <li className="icons text-black">{product.icon}</li>
                <div className="py-1 px-3 helo">{product.discount}</div>
                <button className="btn btn-dark position-absolute bottom-0 w-100">Add to Cart</button>

              </>
            ) : (
              <>
                <img src={product.image} alt={product.name} />
                <li className="icons text-black">{product.icon}</li>
                <button className="btn btn-dark position-absolute bottom-0 w-100">Add to Cart</button>
              </>
            )}
          </div>
        </Link>
        <div className="heading mt-3">
          <p>{product.name}</p>
        </div>
        <div className="d-flex gap-2">
          <p className="price-1">{product.price1}</p>
          <p className="price-2">{product.price2}</p>
        </div>
        <div className="d-flex gap-2 align-content-center">
            <img src={product.star} alt="" className="h-25" />
            <p className="text-muted">({product.reviews})</p>
        </div>
      </div>
    ));
  };

  return (
    <div className="container mt-5 mb-5">
      <div className="row">
        <div className="d-flex align-items-center col-md-12 gap-3 py-3 d-flex justify-content-between">
        <div className="d-flex gap-3">
        <div className="box bg-danger"></div>
        <h2 className="text-black">Just For You</h2>
        </div>
          <button className="bg-white border border-1 border-dark px-5 py-2 text-black">See All</button>
        </div>
      </div>
      <div className="row my-3 d-flex align-items-center">
        {renderProductCards()}
      </div>
    </div>
  );
};

export default JustForYou;
